import{_ as c,I as l,o as h,c as o,b6 as p,j as a,J as i,w as e,a as n}from"./chunks/framework.BUXTSoD9.js";const S=JSON.parse('{"title":"تطوير SaaS لتوليد نصوص تسويقية بالذكاء الاصطناعي — تطبيق عملي","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/assignments/copywriting-platform-supabase/index.md","filePath":"ar-sa/stage-2/assignments/copywriting-platform-supabase/index.md"}'),b={name:"ar-sa/stage-2/assignments/copywriting-platform-supabase/index.md"},u={style:{margin:"32px 0"}};function k(g,s,f,m,_,x){const t=l("StepBar"),r=l("ClientOnly"),d=l("el-card");return h(),o("div",null,[s[2]||(s[2]=p('<h1 id="تطوير-saas-لتوليد-نصوص-تسويقية-بالذكاء-الاصطناعي-—-تطبيق-عملي" tabindex="-1">تطوير SaaS لتوليد نصوص تسويقية بالذكاء الاصطناعي — تطبيق عملي <a class="header-anchor" href="#تطوير-saas-لتوليد-نصوص-تسويقية-بالذكاء-الاصطناعي-—-تطبيق-عملي" aria-label="Permalink to “تطوير SaaS لتوليد نصوص تسويقية بالذكاء الاصطناعي — تطبيق عملي”">​</a></h1><h2 id="نظرة-عامة" tabindex="-1">نظرة عامة <a class="header-anchor" href="#نظرة-عامة" aria-label="Permalink to “نظرة عامة”">​</a></h2><p>يتطلب هذا المشروع <strong>التطبيقي</strong> منك العمل وفق مستند متطلبات منتج (PRD) حقيقي، لبناء منتج SaaS لتوليد نصوص تسويقية بالذكاء الاصطناعي من الصفر وموجه للمطورين المستقلين وفرق المحتوى. ستستخدم Supabase كخدمة خلفية، و Stripe كنظام دفع، لإكمال العملية الكاملة من تحليل المتطلبات إلى النشر والتفعيل.</p><p>هذا هو المشروع <strong>التطبيقي</strong> الشامل في المرحلة الثانية. في الفصول السابقة، تعلمت كل مهارة على حدة — تصميم الصفحات الأمامية، تطوير واجهات الخلفية، عمليات قواعد البيانات، دمج أنظمة الدفع — هذا المشروع يتطلب منك ربطها جميعًا معًا وتسليم نموذج أولي لمنتج قابل للتشغيل.</p><h2 id="المعارف-المسبقة" tabindex="-1">المعارف المسبقة <a class="header-anchor" href="#المعارف-المسبقة" aria-label="Permalink to “المعارف المسبقة”">​</a></h2><p>قبل البدء في هذا المشروع، يجب أن تكون قد أتقنت المحتوى التالي:</p><ul><li>تصميم واجهات المستخدم واستخدام مكتبات المكونات (<a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a>، <a href="./../../frontend/modern-component-library/">مكتبة المكونات الحديثة</a>)</li><li>تصميم وتطوير واجهات الخلفية (<a href="./../../backend/ai-interface-code/">كتابة كود الواجهات</a>)</li><li>أساسيات قواعد البيانات و Supabase (<a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a>)</li><li>دمج أنظمة الدفع (<a href="./../../backend/stripe-payment/">نظام الدفع Stripe</a>)</li><li>سير عمل Git والنشر (<a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>)</li></ul><h2 id="أهداف-التعلم" tabindex="-1">أهداف التعلم <a class="header-anchor" href="#أهداف-التعلم" aria-label="Permalink to “أهداف التعلم”">​</a></h2><p>بعد إكمال هذا المشروع <strong>التطبيقي</strong>، ستتمكن من:</p><ol><li>قراءة وفهم مستند PRD حقيقي واستخراج قائمة مهام التطوير منه</li><li>استخدام الذكاء الاصطناعي لتوليد الصفحات الأمامية وواجهات الخلفية خطوة بخطوة</li><li>استخدام Supabase لتحقيق مصادقة المستخدمين وعمليات قاعدة البيانات</li><li>دمج Stripe لتحقيق وظيفة الاشتراك المدفوع</li><li>بناء لوحة إدارة خلفية وإكمال التكامل الشامل من البداية إلى النهاية</li></ol><h2 id="مقدمة-المشروع" tabindex="-1">مقدمة المشروع <a class="header-anchor" href="#مقدمة-المشروع" aria-label="Permalink to “مقدمة المشروع”">​</a></h2><p>المنتج الذي ستقوم ببنائه هو SaaS لتوليد نصوص تسويقية بالذكاء الاصطناعي، يتضمن ثلاثة أنظمة فرعية:</p><table tabindex="0"><thead><tr><th>النظام الفرعي</th><th>المسؤولية</th></tr></thead><tbody><tr><td><strong>موقع الشركة</strong></td><td>تقديم المنتج، التسعير، الأسئلة الشائعة، تحويل التسجيل</td></tr><tr><td><strong>محطة عمل المستخدم</strong></td><td>إدخال <strong>معلومات</strong> المنتج، توليد النصوص، عرض السجل، ترقية الباقة</td></tr><tr><td><strong>لوحة الإدارة</strong></td><td>إدارة المستخدمين، سجلات التوليد، بيانات الدفع، نظرة عامة على العمليات</td></tr></tbody></table><p>تستخدم الخلفية Supabase لتوفير قاعدة البيانات والمصادقة، و Stripe لمعالجة المدفوعات، ونموذج ذكاء اصطناعي لتوليد النصوص التسويقية.</p><div class="tip custom-block"><p class="custom-block-title">رابط مستند PRD</p><p>مستند متطلبات هذا المشروع على GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/copywriting-platform-supabase/PRD.md" target="_blank" rel="noreferrer">عرض PRD</a></p></div>',15)),a("div",u,[i(r,null,{default:e(()=>[i(t,{active:0,items:[{title:"تحليل المتطلبات",description:"قراءة PRD، توضيح الصفحات والوظائف والمصادقة ونطاق الدفع"},{title:"بناء الهيكل",description:"استخدام AI لتوليد ثلاثة هياكل أمامية (www / app / admin)"},{title:"دمج الخلفية",description:"مصادقة Supabase، واجهة التوليد، دفع Stripe"},{title:"التكامل والنشر",description:"تشغيل شامل من البداية للنهاية، نشر والتحضير للعرض"}]})]),_:1})]),s[3]||(s[3]=p(`<h2 id="الجزء-الأول-تحليل-المتطلبات" tabindex="-1">الجزء الأول: تحليل المتطلبات <a class="header-anchor" href="#الجزء-الأول-تحليل-المتطلبات" aria-label="Permalink to “الجزء الأول: تحليل المتطلبات”">​</a></h2><h3 id="_1-1-قراءة-prd" tabindex="-1">1.1 قراءة PRD <a class="header-anchor" href="#_1-1-قراءة-prd" aria-label="Permalink to “1.1 قراءة PRD”">​</a></h3><p>افتح مستند PRD، وركّز على الإجابة عن الأسئلة التالية:</p><ul><li>كم نقطة دخول في النظام؟ وما هي الصفحات التي يغطيها كل منها؟</li><li>ما هي الوظيفة الأساسية لكل صفحة؟</li><li>ما هي الوحدات والجداول في قاعدة البيانات الموجودة في الخلفية؟</li><li>كيف تم تصميم تسعير الباقات وعملية الدفع والحصة المجانية؟</li><li>ما هو نطاق MVP؟ ما الذي سيتم تنفيذه في الإصدار الأول وما الذي لن يتم؟</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>إذا لم تكن لديك إجابات واضحة على الأسئلة أعلاه، لا تبدأ بكتابة الكود. عدم وضوح المتطلبات هو السبب الأكثر شيوعًا لإعادة العمل.</p></div><h3 id="_1-2-تأكيد-بنية-النظام" tabindex="-1">1.2 تأكيد بنية النظام <a class="header-anchor" href="#_1-2-تأكيد-بنية-النظام" aria-label="Permalink to “1.2 تأكيد بنية النظام”">​</a></h3><p>استنادًا إلى PRD، استخلص البنية العامة للنظام:</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;موقع الشركة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;محطة عمل المستخدم&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;لوحة الإدارة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;المصادقة&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;مهمة توليد النصوص&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;قاعدة البيانات&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;الدفع والباقات&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;لوحة المستخدمين / التوليد / الدفع&quot;]</span></span></code></pre></div><h2 id="الجزء-الثاني-بناء-هيكل-المشروع" tabindex="-1">الجزء الثاني: بناء هيكل المشروع <a class="header-anchor" href="#الجزء-الثاني-بناء-هيكل-المشروع" aria-label="Permalink to “الجزء الثاني: بناء هيكل المشروع”">​</a></h2><h3 id="_2-1-توليد-الصفحات-الأمامية" tabindex="-1">2.1 توليد الصفحات الأمامية <a class="header-anchor" href="#_2-1-توليد-الصفحات-الأمامية" aria-label="Permalink to “2.1 توليد الصفحات الأمامية”">​</a></h3><p>استخدم الذكاء الاصطناعي لتوليد الهيكل الأساسي وجميع الصفحات مع بيانات وهمية أولاً.</p><p>مرجع <strong>للنصيحة</strong> (Prompt):</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني بناءً على PRD الحالي في توليد هيكل أمامي لـ SaaS لتوليد نصوص تسويقية بالذكاء الاصطناعي.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>1. ثلاثة مداخل: www و app و admin</span></span>
<span class="line"><span>2. موقع الشركة يشمل: الصفحة الرئيسية، التسعير، الأسئلة الشائعة</span></span>
<span class="line"><span>3. app يشمل: تسجيل الدخول، التسجيل، محطة العمل، السجل، صفحة الباقات</span></span>
<span class="line"><span>4. admin يشمل: الصفحة الرئيسية للإدارة، إدارة المستخدمين، سجلات التوليد، طلبات الدفع</span></span>
<span class="line"><span>5. توليد فقط هيكل الصفحات وبيانات وهمية بدون ربط واجهات حقيقية</span></span>
<span class="line"><span>6. نمط SaaS حديث وليس عرضًا تجريبيًا صف دراسي</span></span></code></pre></div><h3 id="_2-2-تحسين-الصفحات-الأساسية" tabindex="-1">2.2 تحسين الصفحات الأساسية <a class="header-anchor" href="#_2-2-تحسين-الصفحات-الأساسية" aria-label="Permalink to “2.2 تحسين الصفحات الأساسية”">​</a></h3><p>بعد بناء الهيكل، ركّز على تحسين صفحة محطة عمل توليد النصوص (Dashboard):</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ساعدني في تحسين صفحة /dashboard.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>هذه محطة عمل لتوليد نصوص تسويقية بالذكاء الاصطناعي.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>حقول النموذج على اليسار:</span></span>
<span class="line"><span>- اسم المنتج</span></span>
<span class="line"><span>- مقدمة بجملة واحدة</span></span>
<span class="line"><span>- المستخدم المستهدف</span></span>
<span class="line"><span>- 3 نقاط بيع</span></span>
<span class="line"><span>- قنوات التوزيع (الموقع، WeChat Moments، Xiaohongshu، Douyin، البريد الإلكتروني)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>منطقة **النتائج** على اليمين محجوزة لـ:</span></span>
<span class="line"><span>- العنوان الرئيسي</span></span>
<span class="line"><span>- العنوان الفرعي</span></span>
<span class="line"><span>- CTA</span></span>
<span class="line"><span>- 3 نسخ نصية قصيرة</span></span>
<span class="line"><span>- نص طويل</span></span>
<span class="line"><span></span></span>
<span class="line"><span>استخدم بيانات وهمية أولاً لتشغيل التفاعل.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>- حالة تحميل بعد النقر على &quot;توليد النصوص&quot;</span></span>
<span class="line"><span>- تصميم حالة فارغة لمنطقة **النتائج**</span></span>
<span class="line"><span>- تخطيط متجاوب يعمل بشكل جيد على الشاشات العريضة والضيقة</span></span></code></pre></div><h3 id="_2-3-التحقق-من-بنية-الصفحات" tabindex="-1">2.3 التحقق من بنية الصفحات <a class="header-anchor" href="#_2-3-التحقق-من-بنية-الصفحات" aria-label="Permalink to “2.3 التحقق من بنية الصفحات”">​</a></h3><p>تحقق من كل عنصر:</p><ul><li>[ ] هل مسارات المداخل الثلاثة مستقلة</li><li>[ ] هل عدد الصفحات يتوافق مع PRD</li><li>[ ] هل تخطيط النموذج ومنطقة <strong>النتائج</strong> في Dashboard معقول</li><li>[ ] هل البيانات الوهمية تعرض حالات واجهة مستخدم أساسية</li></ul><h3 id="هل-واجهتك-عقبات؟" tabindex="-1">هل واجهتك عقبات؟ <a class="header-anchor" href="#هل-واجهتك-عقبات؟" aria-label="Permalink to “هل واجهتك عقبات؟”">​</a></h3><p>إذا واجهتك صعوبة في مرحلة بناء الواجهة الأمامية، يمكنك مراجعة هذه الفصول:</p><ul><li><a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/multi-product-ui/">تصميم الصفحات والأزرار وفقًا لإرشادات تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/llm-skills-beautiful/">اجعل واجهتك جميلة باستخدام LLM و Skills</a></li><li><a href="./../../frontend/design-to-code/">من النموذج الأولي للتصميم إلى كود المشروع</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام مكتبة مكونات حديثة</a></li></ul><h2 id="الجزء-الثالث-دمج-الخلفية" tabindex="-1">الجزء الثالث: دمج الخلفية <a class="header-anchor" href="#الجزء-الثالث-دمج-الخلفية" aria-label="Permalink to “الجزء الثالث: دمج الخلفية”">​</a></h2><h3 id="_3-1-ربط-تسجيل-الدخول-عبر-supabase" tabindex="-1">3.1 ربط تسجيل الدخول عبر Supabase <a class="header-anchor" href="#_3-1-ربط-تسجيل-الدخول-عبر-supabase" aria-label="Permalink to “3.1 ربط تسجيل الدخول عبر Supabase”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>اعتبرني مبتدئًا تمامًا وساعدني خطوة بخطوة في ربط تسجيل الدخول عبر Supabase.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>أحتاج منك مساعدتي في:</span></span>
<span class="line"><span>1. ربط المشروع بـ Supabase</span></span>
<span class="line"><span>2. تنفيذ وظائف التسجيل وتسجيل الدخول وتسجيل الخروج</span></span>
<span class="line"><span>3. الانتقال إلى /dashboard بعد تسجيل الدخول بنجاح</span></span>
<span class="line"><span>4. إعادة توجيه المستخدمين غير المسجلين تلقائيًا إلى /login عند محاولة الوصول إلى /dashboard أو /billing أو /admin</span></span>
<span class="line"><span>5. إنشاء جدول profiles</span></span>
<span class="line"><span>6. إنشاء سجل تلقائيًا في جدول profiles بعد تسجيل المستخدم بنجاح</span></span>
<span class="line"><span>7. يجب أن يحتوي جدول profiles على حقول email و role و plan</span></span>
<span class="line"><span></span></span>
<span class="line"><span>متطلبات التنفيذ:</span></span>
<span class="line"><span>- اذكر في كل خطوة الملفات التي يتم تعديلها</span></span>
<span class="line"><span>- لا تقم بتشفير المفاتيح بشكل ثابت</span></span>
<span class="line"><span>- حدد بوضوح الأماكن التي تتطلب عمليات يدوية في لوحة تحكم Supabase</span></span>
<span class="line"><span>- بعد الانتهاء اشرح كيفية التحقق من التسجيل وتسجيل الدخول</span></span></code></pre></div><h3 id="_3-2-ربط-واجهة-التوليد-وقاعدة-البيانات" tabindex="-1">3.2 ربط واجهة التوليد وقاعدة البيانات <a class="header-anchor" href="#_3-2-ربط-واجهة-التوليد-وقاعدة-البيانات" aria-label="Permalink to “3.2 ربط واجهة التوليد وقاعدة البيانات”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>اعتبرني مبتدئًا تمامًا وساعدني في إكمال الوظيفة الأساسية للموقع: توليد نصوص تسويقية وحفظها.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>التأثير المطلوب:</span></span>
<span class="line"><span>1. يملأ المستخدم النموذج في /dashboard وينقر على &quot;توليد النصوص&quot;</span></span>
<span class="line"><span>2. تستلم الخلفية: اسم المنتج والمقدمة والمستخدم المستهدف ونقاط البيع وقنوات التوزيع</span></span>
<span class="line"><span>3. تستدعي الخلفية النموذج لتوليد **النتائج**</span></span>
<span class="line"><span>4. تعرض الصفحة **النتائج** المُولَّدة</span></span>
<span class="line"><span>5. تُحفظ المدخلات والمخرجات في قاعدة البيانات</span></span>
<span class="line"><span>6. يمكن للمستخدم عرض السجل عند العودة مرة أخرى</span></span>
<span class="line"><span></span></span>
<span class="line"><span>أحتاج منك إكمال:</span></span>
<span class="line"><span>- إنشاء واجهة توليد /api/generate</span></span>
<span class="line"><span>- إنشاء جدول generations</span></span>
<span class="line"><span>- تصميم حقول المدخلات والمخرجات</span></span>
<span class="line"><span>- قراءة سجل المستخدم الحالي في صفحة Dashboard</span></span>
<span class="line"><span></span></span>
<span class="line"><span>تجربة المستخدم:</span></span>
<span class="line"><span>- حالة تحميل للزر</span></span>
<span class="line"><span>- رسالة خطأ عند فشل التوليد</span></span>
<span class="line"><span>- حالة فارغة عند عدم وجود سجل</span></span>
<span class="line"><span></span></span>
<span class="line"><span>بعد الانتهاء اذكر:</span></span>
<span class="line"><span>- موقع ملفات الصفحات الأمامية</span></span>
<span class="line"><span>- موقع ملفات واجهات الخلفية</span></span>
<span class="line"><span>- موقع منطق كتابة البيانات إلى قاعدة البيانات</span></span>
<span class="line"><span>- كيفية اختبار سلسلة التوليد الكاملة</span></span></code></pre></div><h3 id="_3-3-ربط-الدفع-عبر-stripe" tabindex="-1">3.3 ربط الدفع عبر Stripe <a class="header-anchor" href="#_3-3-ربط-الدفع-عبر-stripe" aria-label="Permalink to “3.3 ربط الدفع عبر Stripe”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>اعتبرني مبتدئًا تمامًا وساعدني في إضافة أبسط نظام دفع Stripe يعمل لـ LaunchKit.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>لا نحتاج نظامًا معقدًا، فقط نشغّل أبسط سلسلة دفع ممكنة.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>أحتاج منك إكمال:</span></span>
<span class="line"><span>1. صفحة /billing تعرض باقتي free و pro</span></span>
<span class="line"><span>2. انتقال المستخدم إلى Stripe Checkout بعد النقر على ترقية</span></span>
<span class="line"><span>3. العودة إلى الموقع بعد نجاح الدفع</span></span>
<span class="line"><span>4. حفظ **نتائج** الدفع في جدول subscriptions</span></span>
<span class="line"><span>5. تحديث حقل profile.plan بشكل متزامن</span></span>
<span class="line"><span>6. مستخدمو free محدودون بـ 3 توليدات يوميًا، ومستخدمو pro بدون حد</span></span>
<span class="line"><span></span></span>
<span class="line"><span>مبادئ التنفيذ:</span></span>
<span class="line"><span>- شغّل المسار الرئيسي أولاً، لا تقلق بشأن الحدود المعقدة مؤقتًا</span></span>
<span class="line"><span>- اذكر بوضوح الأماكن التي تحتاج إعدادًا في لوحة تحكم Stripe</span></span>
<span class="line"><span>- بعد الانتهاء اشرح كيفية اختبار سلسلة الدفع الكاملة</span></span></code></pre></div><h3 id="_3-4-بناء-لوحة-الإدارة-الخلفية" tabindex="-1">3.4 بناء لوحة الإدارة الخلفية <a class="header-anchor" href="#_3-4-بناء-لوحة-الإدارة-الخلفية" aria-label="Permalink to “3.4 بناء لوحة الإدارة الخلفية”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>اعتبرني مبتدئًا تمامًا وساعدني في إنشاء لوحة إدارة خلفية بسيطة وقابلة للاستخدام.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>فقط للمسؤولين.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>أحتاج منك إكمال:</span></span>
<span class="line"><span>1. فقط المستخدمون الذين role = admin يمكنهم الوصول إلى /admin</span></span>
<span class="line"><span>2. تحتوي لوحة الإدارة على 3 علامات تبويب: قائمة المستخدمين، سجلات التوليد، حالة الاشتراك</span></span>
<span class="line"><span>3. تعرض قائمة المستخدمين: البريد الإلكتروني، الباقة، تاريخ الإنشاء</span></span>
<span class="line"><span>4. تعرض سجلات التوليد: المستخدم، اسم المنتج، القناة، تاريخ الإنشاء</span></span>
<span class="line"><span>5. تعرض حالة الاشتراك: المستخدم، الباقة، حالة الدفع</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>- واجهة بسيطة وواضحة</span></span>
<span class="line"><span>- استخدام الجداول وعلامات التبويب والشارات من مكتبة المكونات الحالية</span></span>
<span class="line"><span>- بعد الانتهاء اشرح كيفية تعيين الحساب كمسؤول</span></span></code></pre></div><h3 id="هل-واجهتك-عقبات؟-1" tabindex="-1">هل واجهتك عقبات؟ <a class="header-anchor" href="#هل-واجهتك-عقبات؟-1" aria-label="Permalink to “هل واجهتك عقبات؟”">​</a></h3><p>إذا واجهتك صعوبة في مرحلة تطوير الخلفية، يمكنك مراجعة هذه الفصول:</p><ul><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">كتابة كود الواجهات والتوثيق بمساعدة النماذج الكبيرة</a></li><li><a href="./../../backend/stripe-payment/">كيفية دمج أنظمة الدفع مثل Stripe</a></li></ul><h2 id="الجزء-الرابع-التكامل-والنشر" tabindex="-1">الجزء الرابع: التكامل والنشر <a class="header-anchor" href="#الجزء-الرابع-التكامل-والنشر" aria-label="Permalink to “الجزء الرابع: التكامل والنشر”">​</a></h2><h3 id="_4-1-اختبار-شامل-من-البداية-للنهاية" tabindex="-1">4.1 اختبار شامل من البداية للنهاية <a class="header-anchor" href="#_4-1-اختبار-شامل-من-البداية-للنهاية" aria-label="Permalink to “4.1 اختبار شامل من البداية للنهاية”">​</a></h3><p>تحقق من السيناريوهات التالية على الأقل:</p><ul><li>تسجيل ← تسجيل دخول ← توليد نصوص ← عرض السجل ← ترقية الباقة</li><li>تسجيل دخول المسؤول ← عرض بيانات المستخدمين ← عرض سجلات التوليد ← عرض حالة الدفع</li></ul><p>فحوصات ما قبل النشر:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>اعتبرني مبتدئًا تمامًا وساعدني في التحقق مما إذا كان المشروع جاهزًا للنشر.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>نقاط الفحص الرئيسية:</span></span>
<span class="line"><span>- هل متغيرات البيئة مكتملة</span></span>
<span class="line"><span>- هل عنوان إعادة توجيه تسجيل الدخول صحيح</span></span>
<span class="line"><span>- هل عنوان إعادة توجيه دفع Stripe صحيح</span></span>
<span class="line"><span>- هل تنقص الصفحات حالة تحميل أو حالة فارغة أو رسالة خطأ</span></span>
<span class="line"><span>- هل يحتوي README على تعليمات التشغيل والنشر</span></span>
<span class="line"><span></span></span>
<span class="line"><span>أحتاج منك:</span></span>
<span class="line"><span>1. سرد العناصر التي تحتاج إصلاحًا مرتبة حسب الأولوية</span></span>
<span class="line"><span>2. تحديد ما يجب إصلاحه أولًا</span></span>
<span class="line"><span>3. شرح **خطوات** النشر بعد الإصلاح</span></span></code></pre></div><h3 id="_4-2-النشر" tabindex="-1">4.2 النشر <a class="header-anchor" href="#_4-2-النشر" aria-label="Permalink to “4.2 النشر”">​</a></h3><p>انشر المشروع على بيئة الإنترنت العامة. راجع دروس النشر: <a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>.</p><h2 id="المخرجات-المطلوبة" tabindex="-1">المخرجات المطلوبة <a class="header-anchor" href="#المخرجات-المطلوبة" aria-label="Permalink to “المخرجات المطلوبة”">​</a></h2><p>بعد إكمال هذا المشروع، يجب عليك تقديم المحتوى التالي:</p><ul><li>[ ] رابط عرض تجريبي عبر الإنترنت قابل للوصول</li><li>[ ] رابط مستودع الكود المصدري (مع README)</li><li>[ ] مستند PRD</li><li>[ ] لقطات شاشة للصفحات الأساسية (الصفحة الرئيسية، Dashboard، Billing، Admin)</li><li>[ ] فيديو عرض تجريبي مدته 60 ثانية (يغطي التسجيل ← التوليد ← الدفع ← لوحة الإدارة)</li></ul><p>يجب أن يحتوي README على الأقل: <strong>مقدمة المشروع</strong>، شرح الصفحات الأساسية، حزم التقنيات، <strong>خطوات</strong> التشغيل المحلي، قائمة متغيرات البيئة.</p><h2 id="معايير-التقييم" tabindex="-1">معايير التقييم <a class="header-anchor" href="#معايير-التقييم" aria-label="Permalink to “معايير التقييم”">​</a></h2><table tabindex="0"><thead><tr><th>البعد</th><th>المتطلبات الأساسية</th><th>المتطلبات المتقدمة</th></tr></thead><tbody><tr><td>اكتمال المنتج</td><td>الصفحة الرئيسية وتسجيل الدخول و Dashboard و Billing و Admin جميعها قابلة للوصول</td><td>نصوص الصفحة الرئيسية وأسلوبها البصري يشبهان SaaS حقيقي</td></tr><tr><td>حلقة الأعمال</td><td>التسجيل ← تسجيل الدخول ← التوليد ← عرض السجل يمكن تشغيله بالكامل</td><td>الفرق في الصلاحيات بين free و Pro واضح ومرئي</td></tr><tr><td>صحة البيانات</td><td><strong>نتائج</strong> التوليد وحالة الدفع محفوظة في قاعدة البيانات</td><td>توجد رسائل خطأ وحالات فارغة وحالة تحميل واضحة</td></tr><tr><td>الصلاحيات والأمان</td><td>لا يمكن للمستخدمين غير المسجلين الوصول للصفحات المحمية، ولا يمكن للمستخدمين العاديين دخول Admin</td><td>يوجد تحقق أساسي من المدخلات ومصادقة من جانب الخادم</td></tr><tr><td>جودة التسليم</td><td>يمكن تشغيل المشروع محليًا ونشره على الإنترنت</td><td>README واضح، وهيكل فيديو العرض التجريبي مكتمل</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>إذا شعرت أن المهمة كبيرة جدًا، تذكر مبدأ واحد: <strong>اضمن أولًا أن &quot;كل شيء يعمل&quot;، ثم اسعَ لـ &quot;أن يكون جميلًا&quot;.</strong></p></div><h2 id="فحوصات-ما-قبل-التقديم" tabindex="-1">فحوصات ما قبل التقديم <a class="header-anchor" href="#فحوصات-ما-قبل-التقديم" aria-label="Permalink to “فحوصات ما قبل التقديم”">​</a></h2>`,50)),i(d,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:e(()=>[...s[0]||(s[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"نظرة أخيرة قبل التقديم",-1)])]),default:e(()=>[s[1]||(s[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" الصفحة الرئيسية وتسجيل الدخول و Dashboard و Billing و Admin **مكتملة** جميعها")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" يمكن للمستخدم التسجيل وتسجيل الدخول والخروج")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" **نتائج** التوليد محفوظة فعليًا في قاعدة البيانات")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" سلسلة الدفع الرئيسية تعمل")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" يمكن للمسؤول عرض المستخدمين وسجلات التوليد وحالة الدفع")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),n(" تم نشر المشروع على الإنترنت العام")])])],-1))]),_:1}),s[4]||(s[4]=p('<h2 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/multi-product-ui/">تصميم الصفحات والأزرار وفقًا لإرشادات تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/llm-skills-beautiful/">اجعل واجهتك جميلة باستخدام LLM و Skills</a></li><li><a href="./../../frontend/design-to-code/">من النموذج الأولي للتصميم إلى كود المشروع</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام مكتبة مكونات حديثة</a></li><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">كتابة كود الواجهات والتوثيق بمساعدة النماذج الكبيرة</a></li><li><a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a></li><li><a href="./../../backend/stripe-payment/">كيفية دمج أنظمة الدفع مثل Stripe</a></li></ul>',2))])}const P=c(b,[["render",k]]);export{S as __pageData,P as default};
